//! Disequality patterns and the private closure rules generated by the extension.
//!
//! Assertions become per-sort Ne relations. Root `known-disequal` patterns read
//! those relations, and `contradiction` reads their shared zero-argument marker.
//! Separate injectivity adds guarded cancellation and upward propagation only.
//! Each user run is followed by saturation of the private rules; observations
//! also close pending top-level assertions and unions without disrupting batches.

mod terms;

use egglog::{
    ArcSort, AtomTerm, CommandMacro, CommandOutput, Context, EGraph, Error, Primitive, PurePrim,
    PureState, TypeError, TypeInfo, Value,
    ast::{
        Action, Actions, Command, Expr, Fact, FunctionDecl, Literal, Macro, ParseError, Parser,
        ResolvedExpr, ResolvedFact, Rule, RuleEvalMode, RunConfig, Schedule, Sexp, Span,
    },
    constraint::{Constraint, TypeConstraint},
    util::{FreshGen, SymbolGen},
};
use egglog_reports::RunReport;
use std::{collections::BTreeMap, sync::Arc};

/// Immutable private names; signatures and rules follow the graph's normal scopes.
#[derive(Clone, Default)]
pub(crate) struct Encoding {
    pub(crate) ruleset: String,
    pub(crate) contradiction: String,
    pub(crate) ne_prefix: String,
    assertion: String,
}

pub(crate) fn add_disequality_support(egraph: &mut EGraph) {
    let symbols = &mut egraph.parser.symbol_gen;
    let encoding = Encoding {
        ruleset: symbols.fresh("disequality"),
        contradiction: symbols.fresh("disequality-contradiction"),
        ne_prefix: symbols.fresh("disequality-ne"),
        assertion: symbols.fresh("disequal"),
    };
    *egraph.extension_state_or_default::<Encoding>() = encoding.clone();
    egraph.add_pure_primitive(QueryPattern("known-disequal"), None);
    egraph.add_pure_primitive(QueryPattern("contradiction"), None);
    egraph
        .parser
        .add_action_macro(Arc::new(Disequal(encoding.assertion.clone())));
    crate::injectivity::add_injectivity_support(egraph, encoding.clone());
    egraph
        .command_macros_mut()
        .register(Arc::new(LowerDisequality(encoding)));
}

/// Return macros that lower injectivity and disequality to constructors and
/// guarded rewrites, for [`crate::slotted::Compiler::with_source_macros`].
pub fn source_macros() -> EGraph {
    let mut graph = EGraph::default();
    graph.parser.symbol_gen = SymbolGen::new("_disequality_".into());
    add_disequality_support(&mut graph);
    let encoding = graph.extension_state::<Encoding>().unwrap().clone();
    graph
        .command_macros_mut()
        .register(Arc::new(terms::Terms(encoding)));
    graph
}

/// Close the extension invariant around interpreter-driven scheduler steps.
/// The private schedule bypasses user instrumentation and contributes its report.
pub(crate) fn close(egraph: &mut EGraph) -> Result<RunReport, Error> {
    let Some(encoding) = egraph.extension_state::<Encoding>().cloned() else {
        return Ok(RunReport::default());
    };
    if egraph
        .type_info()
        .get_func_type(&encoding.contradiction)
        .is_none()
    {
        return Ok(RunReport::default());
    }
    let mut report = RunReport::default();
    for output in egraph.run_program(vec![Command::RunSchedule(
        encoding.closure_schedule(egglog::span!()),
    )])? {
        if let CommandOutput::RunSchedule(step) = output {
            report.union(step);
        }
    }
    Ok(report)
}

#[derive(Clone)]
struct QueryPattern(&'static str);
impl Primitive for QueryPattern {
    fn name(&self) -> &str {
        self.0
    }
    fn get_type_constraints(&self, span: &Span) -> Box<dyn TypeConstraint> {
        Box::new(QueryConstraint(self.0, span.clone()))
    }
}
struct QueryConstraint(&'static str, Span);
impl TypeConstraint for QueryConstraint {
    fn get(
        &self,
        arguments: &[AtomTerm],
        types: &TypeInfo,
    ) -> Vec<Box<dyn Constraint<AtomTerm, ArcSort>>> {
        let unit = types.get_sort_by_name("Unit").unwrap();
        if self.0 == "contradiction" {
            return crate::type_constraints::exact_signatures(
                self.0,
                &self.1,
                arguments,
                1,
                [vec![unit.clone()]],
            );
        }
        let mut sorts = types.get_arcsorts_by(|sort| types.is_sort_unionable(sort));
        sorts.sort_by_key(|sort| sort.name().to_owned());
        crate::type_constraints::exact_signatures(
            self.0,
            &self.1,
            arguments,
            3,
            sorts
                .into_iter()
                .map(|sort| vec![sort.clone(), sort, unit.clone()]),
        )
    }
}
impl PurePrim for QueryPattern {
    fn apply<'a, 'db>(&self, _state: PureState<'a, 'db>, _args: &[Value]) -> Option<Value> {
        None
    }
}

impl Encoding {
    pub(crate) fn closure_schedule(&self, span: Span) -> Schedule {
        Schedule::Saturate(
            span.clone(),
            Box::new(Schedule::Run(
                span,
                RunConfig {
                    ruleset: self.ruleset.clone(),
                    until: None,
                },
            )),
        )
    }

    /// Install physical support once per scoped sort, using live type signatures.
    pub(crate) fn support_commands(
        &self,
        sorts: BTreeMap<String, Span>,
        support_span: Option<Span>,
        symbols: &mut SymbolGen,
        types: &TypeInfo,
    ) -> Vec<Command> {
        let Some(span) = sorts.values().next().cloned().or(support_span) else {
            return vec![];
        };
        let mut commands = Vec::new();
        if types.get_func_type(&self.contradiction).is_none() {
            commands.push(Command::AddRuleset(span.clone(), self.ruleset.clone()));
            commands.push(Command::Relation {
                span,
                name: self.contradiction.clone(),
                inputs: vec![],
            });
        }
        for (sort, span) in sorts {
            let name = format!("{}-{sort}", self.ne_prefix);
            if types.get_func_type(&name).is_some() {
                continue;
            }
            commands.push(Command::Relation {
                span: span.clone(),
                name: name.clone(),
                inputs: vec![sort.clone(), sort.clone()],
            });
            let x = Expr::Var(span.clone(), symbols.fresh("disequality-left"));
            let y = Expr::Var(span.clone(), symbols.fresh("disequality-right"));
            for (suffix, body, head) in [
                (
                    "self",
                    vec![Fact::Fact(Expr::Call(
                        span.clone(),
                        name.clone(),
                        vec![x.clone(), x.clone()],
                    ))],
                    Expr::Call(span.clone(), self.contradiction.clone(), vec![]),
                ),
                (
                    "symmetric",
                    vec![Fact::Fact(Expr::Call(
                        span.clone(),
                        name.clone(),
                        vec![x.clone(), y.clone()],
                    ))],
                    Expr::Call(span.clone(), name, vec![y, x]),
                ),
            ] {
                commands.push(Command::Rule {
                    rule: Rule {
                        span: span.clone(),
                        name: symbols.fresh(&format!("disequality-{suffix}-{sort}")),
                        ruleset: self.ruleset.clone(),
                        body,
                        head: Actions::singleton(Action::Expr(span.clone(), head)),
                        eval_mode: RuleEvalMode::Seminaive,
                        no_decomp: false,
                        include_subsumed: true,
                    },
                });
            }
        }
        commands
    }

    /// Preserve mutation batches while restoring closure at executable boundaries.
    /// Nested fail commands execute inside rollback, so their closure steps must too.
    fn instrument_commands(&self, commands: Vec<Command>, mut pending: bool) -> Vec<Command> {
        let mut result = Vec::new();
        for mut command in commands {
            match &mut command {
                Command::Action(_) | Command::Actions(_) | Command::LetBegin(..) => pending = true,
                Command::RunSchedule(schedule) => {
                    if !matches!(schedule, Schedule::Saturate(_, inner) if matches!(inner.as_ref(), Schedule::Run(_, config) if config.ruleset == self.ruleset))
                    {
                        self.instrument_schedule(schedule);
                        if pending {
                            *schedule = Schedule::Sequence(
                                egglog::span!(),
                                vec![self.closure_schedule(egglog::span!()), schedule.clone()],
                            );
                        }
                    }
                    pending = false;
                }
                // The extended interpreter closes its own boundaries and merges
                // maintenance into its single combined report.
                Command::UserDefined(_, name, _) if name == "run-schedule" => pending = true,
                Command::Constructor { .. }
                | Command::Datatype { .. }
                | Command::Datatypes { .. }
                | Command::Sort { .. }
                | Command::Function { .. }
                | Command::Relation { .. }
                | Command::Rule { .. }
                | Command::Rewrite(..)
                | Command::BiRewrite(..)
                | Command::AddRuleset(..) => {}
                _ => {
                    if pending {
                        result.push(Command::RunSchedule(self.closure_schedule(egglog::span!())));
                    }
                    if let Command::Fail(_, nested) = &mut command {
                        *nested = self.instrument_commands(std::mem::take(nested), false);
                    }
                    // Commands such as extraction/input can also insert terms.
                    pending = !matches!(&command, Command::Check(..) | Command::Fail(..));
                }
            }
            result.push(command);
        }
        result
    }

    fn instrument_schedule(&self, schedule: &mut Schedule) {
        match schedule {
            Schedule::Run(span, config) if config.ruleset != self.ruleset => {
                let span = span.clone();
                *schedule = Schedule::Sequence(
                    span.clone(),
                    vec![schedule.clone(), self.closure_schedule(span)],
                );
            }
            Schedule::Run(..) => {}
            Schedule::Saturate(_, inner) | Schedule::Repeat(_, _, inner) => {
                self.instrument_schedule(inner)
            }
            Schedule::Sequence(_, schedules) => {
                for inner in schedules {
                    self.instrument_schedule(inner);
                }
            }
        }
    }
}

struct Disequal(String);
impl Macro<Vec<Action>> for Disequal {
    fn name(&self) -> &str {
        "disequal"
    }
    fn parse(
        &self,
        args: &[Sexp],
        span: Span,
        parser: &mut Parser,
    ) -> Result<Vec<Action>, ParseError> {
        let [lhs, rhs] = args else {
            return Err(ParseError(span, "usage: (disequal <expr> <expr>)".into()));
        };
        Ok(vec![Action::Expr(
            span.clone(),
            Expr::Call(
                span,
                self.0.clone(),
                vec![parser.parse_expr(lhs)?, parser.parse_expr(rhs)?],
            ),
        )])
    }
}
struct LowerDisequality(Encoding);

impl CommandMacro for LowerDisequality {
    fn preserves_closed_constructor_action(&self, expression_head: Option<&str>) -> bool {
        !matches!(expression_head, Some("known-disequal" | "contradiction"))
            && expression_head != Some(self.0.assertion.as_str())
    }

    fn transform(
        &self,
        command: Command,
        symbols: &mut SymbolGen,
        types: &TypeInfo,
    ) -> Result<Vec<Command>, Error> {
        let expanded = crate::fresh_macro::FreshMacro::new().transform(command, symbols, types)?;
        let expanded_fresh = expanded.len() > 1;
        let mut local_types = std::borrow::Cow::Borrowed(types);
        let mut result = Vec::new();
        for command in expanded {
            // FreshMacro emits a constructor before its rule. Make that signature
            // visible to this pass without installing anything in the live graph.
            if expanded_fresh
                && let Command::Constructor {
                    span,
                    name,
                    schema,
                    cost,
                    unextractable,
                    hidden,
                    role,
                } = &command
            {
                let mut declaration = FunctionDecl::constructor(
                    span.clone(),
                    name.clone(),
                    schema.clone(),
                    *cost,
                    *unextractable,
                    *hidden,
                );
                declaration.role = *role;
                local_types
                    .to_mut()
                    .typecheck_function(symbols, &declaration)?;
                result.push(command);
            } else {
                result.extend(self.lower(command, symbols, &local_types)?);
            }
        }
        Ok(result)
    }
}

impl LowerDisequality {
    fn lower(
        &self,
        mut command: Command,
        symbols: &mut SymbolGen,
        types: &TypeInfo,
    ) -> Result<Vec<Command>, Error> {
        let mut sorts = BTreeMap::new();
        let mut support_span = None;
        self.lower_command(&mut command, symbols, types, &mut sorts, &mut support_span)?;
        let active = types.get_func_type(&self.0.contradiction).is_some()
            || !sorts.is_empty()
            || support_span.is_some();
        let mut commands = self.0.support_commands(sorts, support_span, symbols, types);
        if active {
            commands.extend(self.0.instrument_commands(vec![command], true));
        } else {
            commands.push(command);
        }
        Ok(commands)
    }

    fn lower_command(
        &self,
        command: &mut Command,
        symbols: &mut SymbolGen,
        types: &TypeInfo,
        sorts: &mut BTreeMap<String, Span>,
        support_span: &mut Option<Span>,
    ) -> Result<(), Error> {
        match command {
            Command::Rule { rule }
                if contains_disequal(&rule.head, &self.0.assertion)
                    || contains_query(&rule.body) =>
            {
                if contains_query(&rule.body) {
                    *support_span = Some(rule.span.clone());
                }
                // Union has the same operand constraints as disequal. Use it only
                // for inference, never execution, so head uses can constrain the body.
                let mut probe = rule.clone();
                probe.head = union_probe(&rule.head, &self.0.assertion);
                let resolved = types.typecheck_rule(symbols, &probe, false)?;
                rule.body = self.0.lower_typed_facts(resolved.body, sorts)?;
                self.0
                    .lower_typed_actions(&mut rule.head, resolved.head, sorts);
            }
            Command::Action(action) if matches!(&*action, Action::Expr(_, Expr::Call(_, head, _)) if head == &self.0.assertion) =>
            {
                let Action::Expr(span, Expr::Call(_, _, args)) = action else {
                    unreachable!()
                };
                let [lhs, rhs] = args.as_slice() else {
                    unreachable!("parser checks disequal arity")
                };
                let left = operand_sort(types, symbols, lhs)?;
                let right = operand_sort(types, symbols, rhs)?;
                if left.name() != right.name() {
                    return Err(TypeError::Mismatch {
                        expr: rhs.clone(),
                        expected: left,
                        actual: right,
                    }
                    .into());
                }
                if !left.is_eq_sort() {
                    return Err(TypeError::NonEqsortUnion(left, span.clone()).into());
                }
                if !types.is_sort_unionable(&left) {
                    return Err(TypeError::NonUnionableSort(left, span.clone()).into());
                }
                sorts.insert(left.name().into(), span.clone());
                *action = Action::Expr(
                    span.clone(),
                    Expr::Call(
                        span.clone(),
                        format!("{}-{}", self.0.ne_prefix, left.name()),
                        args.to_vec(),
                    ),
                );
            }
            Command::LetBegin(span, _, actions) if matches!(actions.0.last(), Some(Action::Expr(_, Expr::Call(_, head, _))) if head == &self.0.assertion) =>
            {
                return Err(Error::DesugarError(
                    span.clone(),
                    "let-begin must end with a value, not disequal".into(),
                ));
            }
            Command::Actions(actions) | Command::LetBegin(_, _, actions)
                if contains_disequal(actions, &self.0.assertion) =>
            {
                let resolved = types.typecheck_standalone_actions(
                    symbols,
                    &union_probe(actions, &self.0.assertion),
                    &Default::default(),
                    Context::Full,
                )?;
                self.0.lower_typed_actions(actions, resolved, sorts);
            }
            Command::Check(_, facts) | Command::Prove(_, facts) if contains_query(facts) => {
                *support_span = Some(egglog::span!());
                *facts = self
                    .0
                    .lower_typed_facts(types.typecheck_facts(symbols, facts)?, sorts)?;
            }
            Command::Rewrite(_, rewrite, _) | Command::BiRewrite(_, rewrite)
                if contains_query(&rewrite.conditions) =>
            {
                *support_span = Some(rewrite.span.clone());
                let value = Expr::Var(rewrite.span.clone(), symbols.fresh("disequality-rewrite"));
                let mut body = vec![Fact::Eq(
                    rewrite.span.clone(),
                    value.clone(),
                    rewrite.lhs.clone(),
                )];
                body.extend(rewrite.conditions.clone());
                let probe = Rule {
                    span: rewrite.span.clone(),
                    name: String::new(),
                    ruleset: String::new(),
                    body,
                    head: Actions::singleton(Action::Union(
                        rewrite.span.clone(),
                        value,
                        rewrite.rhs.clone(),
                    )),
                    eval_mode: RuleEvalMode::Seminaive,
                    no_decomp: false,
                    include_subsumed: false,
                };
                let resolved = types.typecheck_rule(symbols, &probe, false)?;
                rewrite.conditions = self
                    .0
                    .lower_typed_facts(resolved.body.into_iter().skip(1).collect(), sorts)?;
            }
            Command::Fail(_, commands) => {
                for command in commands {
                    self.lower_command(command, symbols, types, sorts, support_span)?;
                }
            }
            Command::RunSchedule(schedule) => {
                self.0
                    .lower_schedule_queries(schedule, symbols, types, sorts, support_span)?;
            }
            _ => {}
        }
        // Relation calls in actions insert rows. Never turn a read predicate
        // into an insertion: every remaining occurrence is outside query facts.
        let mut unsupported = None;
        let mut inspect = |expr: Expr| {
            if let Expr::Call(span, head, args) = &expr
                && (matches!(head.as_str(), "known-disequal" | "contradiction")
                    || head == "unstable-fn"
                        && matches!(args.first(), Some(Expr::Lit(_, Literal::String(name))) if matches!(name.as_str(), "known-disequal" | "contradiction")))
            {
                unsupported = Some(span.clone());
            }
            expr
        };
        if let Command::UserDefined(_, name, args) = command {
            for arg in args {
                // Extended schedules lower their until expressions through
                // Command::Check at execution time. Other expressions, such as
                // eval actions or scheduler-builder arguments, must reject it.
                let expression = if name == "run-schedule" {
                    mask_schedule_queries(arg.clone())
                } else {
                    arg.clone()
                };
                let _ = expression.visit_exprs(&mut inspect);
            }
        } else {
            let _ = command.clone().visit_exprs(&mut inspect);
        }
        if let Some(span) = unsupported {
            return Err(ParseError(
                span,
                "known-disequal and contradiction are root query patterns only".into(),
            )
            .into());
        }
        Ok(())
    }
}

fn mask_schedule_queries(expr: Expr) -> Expr {
    let Expr::Call(span, name, mut args) = expr else {
        return expr;
    };
    match name.as_str() {
        "run" | "run-with" => {
            let rest = if name == "run-with" {
                match args.as_slice() {
                    [Expr::Var(..), rest @ ..] => rest,
                    _ => &[],
                }
            } else {
                &args
            };
            let has_condition = match rest {
                [Expr::Var(_, until), _] | [Expr::Var(_, _), Expr::Var(_, until), _] => {
                    until == ":until"
                }
                _ => false,
            };
            if has_condition {
                let condition = args.last_mut().unwrap();
                *condition = Expr::Lit(condition.span(), Literal::Unit);
            }
        }
        "seq" | "saturate" | "repeat" | "run-schedule" => {
            args = args.into_iter().map(mask_schedule_queries).collect();
        }
        _ => {}
    }
    Expr::Call(span, name, args)
}

impl Encoding {
    /// Type-check whole facts for joint inference, then lower root patterns only.
    fn lower_typed_facts(
        &self,
        facts: Vec<ResolvedFact>,
        sorts: &mut BTreeMap<String, Span>,
    ) -> Result<Vec<Fact>, Error> {
        facts
            .into_iter()
            .map(|fact| {
                Ok(match fact {
                    ResolvedFact::Fact(ResolvedExpr::Call(span, call, args))
                        if matches!(call.name(), "known-disequal" | "contradiction") =>
                    {
                        let name = if call.name() == "contradiction" {
                            self.contradiction.clone()
                        } else {
                            let egglog::ResolvedCall::Primitive(primitive) = call else {
                                unreachable!("inference-only pattern primitive");
                            };
                            let sort = primitive.input()[0].name();
                            sorts.insert(sort.into(), span.clone());
                            format!("{}-{sort}", self.ne_prefix)
                        };
                        Fact::Fact(Expr::Call(
                            span,
                            name,
                            args.into_iter()
                                .map(unresolved_expr)
                                .collect::<Result<_, _>>()?,
                        ))
                    }
                    ResolvedFact::Fact(expr) => Fact::Fact(unresolved_expr(expr)?),
                    ResolvedFact::Eq(span, lhs, rhs) => {
                        Fact::Eq(span, unresolved_expr(lhs)?, unresolved_expr(rhs)?)
                    }
                })
            })
            .collect()
    }

    fn lower_schedule_queries(
        &self,
        schedule: &mut Schedule,
        symbols: &mut SymbolGen,
        types: &TypeInfo,
        sorts: &mut BTreeMap<String, Span>,
        support_span: &mut Option<Span>,
    ) -> Result<(), Error> {
        match schedule {
            Schedule::Saturate(_, inner) | Schedule::Repeat(_, _, inner) => {
                self.lower_schedule_queries(inner, symbols, types, sorts, support_span)?
            }
            Schedule::Sequence(_, schedules) => {
                for inner in schedules {
                    self.lower_schedule_queries(inner, symbols, types, sorts, support_span)?;
                }
            }
            Schedule::Run(span, config) => {
                if let Some(facts) = &mut config.until
                    && contains_query(facts)
                {
                    *support_span = Some(span.clone());
                    *facts =
                        self.lower_typed_facts(types.typecheck_facts(symbols, facts)?, sorts)?;
                }
            }
        }
        Ok(())
    }
}

/// Reconstruct typed ordinary expressions while rejecting nested query patterns.
fn unresolved_expr(expr: ResolvedExpr) -> Result<Expr, Error> {
    Ok(match expr {
        ResolvedExpr::Var(span, var) => Expr::Var(span, var.name),
        ResolvedExpr::Lit(span, literal) => Expr::Lit(span, literal),
        ResolvedExpr::Call(span, call, args) => {
            if matches!(call.name(), "known-disequal" | "contradiction") {
                return Err(ParseError(
                    span,
                    "known-disequal and contradiction are root query patterns only".into(),
                )
                .into());
            }
            Expr::Call(
                span,
                call.name().into(),
                args.into_iter()
                    .map(unresolved_expr)
                    .collect::<Result<_, _>>()?,
            )
        }
    })
}

fn contains_query(facts: &[Fact]) -> bool {
    facts.iter().any(|fact| {
        let mut found = false;
        let _ = fact.clone().visit_exprs(&mut |expr| {
            found |= matches!(&expr, Expr::Call(_, name, _) if matches!(name.as_str(), "known-disequal" | "contradiction"));
            expr
        });
        found
    })
}

/// Rewrite assertions with the operand sorts already checked by the union probe.
impl Encoding {
    fn lower_typed_actions(
        &self,
        actions: &mut Actions,
        resolved: egglog::ast::GenericActions<egglog::ResolvedCall, egglog::ResolvedVar>,
        sorts: &mut BTreeMap<String, Span>,
    ) {
        for (action, typed) in actions.0.iter_mut().zip(resolved.0) {
            if let Action::Expr(span, Expr::Call(_, head, args)) = action
                && head == &self.assertion
            {
                let egglog::ast::GenericAction::Union(_, lhs, _) = typed else {
                    unreachable!()
                };
                let sort = match lhs {
                    egglog::ast::ResolvedExpr::Var(_, var) => var.sort,
                    egglog::ast::ResolvedExpr::Call(_, call, _) => call.output().clone(),
                    egglog::ast::ResolvedExpr::Lit(_, literal) => {
                        egglog::sort::literal_sort(&literal)
                    }
                };
                sorts.insert(sort.name().into(), span.clone());
                *action = Action::Expr(
                    span.clone(),
                    Expr::Call(
                        span.clone(),
                        format!("{}-{}", self.ne_prefix, sort.name()),
                        args.to_vec(),
                    ),
                );
            }
        }
    }
}

/// Use union's operand constraints without ever executing the inferred action.
fn union_probe(actions: &Actions, assertion: &str) -> Actions {
    actions.clone().visit_actions(&mut |action| match action {
        Action::Expr(span, Expr::Call(_, head, mut args)) if head == assertion => {
            Action::Union(span, args.remove(0), args.remove(0))
        }
        action => action,
    })
}

/// Declared calls already determine their result sort. Avoid solving the full
/// expression twice; the emitted action still validates all argument types.
fn operand_sort(
    types: &TypeInfo,
    symbols: &mut SymbolGen,
    expr: &Expr,
) -> Result<ArcSort, TypeError> {
    let declared = match expr {
        Expr::Var(_, name) => types.get_global_sort(name),
        Expr::Call(_, head, _) if !types.is_primitive(head) => {
            types.get_func_type(head).map(|f| f.output())
        }
        _ => None,
    };
    match declared {
        Some(sort) => Ok(sort.clone()),
        None => types.infer_expr_sort(symbols, expr, &[], Context::Full),
    }
}

fn contains_disequal(actions: &Actions, assertion: &str) -> bool {
    actions
        .0
        .iter()
        .any(|a| matches!(a, Action::Expr(_, Expr::Call(_, head, _)) if head == assertion))
}
